<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class RhContrat extends Model { use \Illuminate\Database\Eloquent\SoftDeletes; protected $table='rh_contrats'; protected $guarded=[]; protected $casts=['date_signature'=>'date','date_debut'=>'date','date_fin'=>'date','date_fin_reelle'=>'date','salaire_base'=>'decimal:2','primes_fixes'=>'decimal:2','indemnites_fixes'=>'decimal:2','jours_reference'=>'decimal:2','heures_reference'=>'decimal:2','jours_travail'=>'array','avantages'=>'array','details_specifiques'=>'array','valide_le'=>'datetime']; public function employe(){return $this->belongsTo(Employe::class);} public function ancienUtilisateur(){return $this->belongsTo(User::class,'user_id');} public function typeContrat(){return $this->belongsTo(RhTypeContrat::class);} public function avenants(){return $this->hasMany(RhAvenantContrat::class,'contrat_id');} public function paies(){return $this->hasMany(RhPaie::class,'contrat_id');} public function precedent(){return $this->belongsTo(self::class,'contrat_precedent_id');} public function renouvellements(){return $this->hasMany(self::class,'contrat_precedent_id');} public function superieur(){return $this->belongsTo(Employe::class,'superieur_id');} public function service(){return $this->belongsTo(RhService::class,'service_id');} public function fonction(){return $this->belongsTo(Fonction::class,'fonction_id');} public function departement(){return $this->belongsTo(Departement::class,'departement_id');} }
